import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"11.3 面向对象、设计模式与程序语言词汇 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/03-面向对象与程序语言词汇.md","filePath":"11-专业英语/03-面向对象与程序语言词汇.md"}'),o={name:"11-专业英语/03-面向对象与程序语言词汇.md"};function n(i,t,s,c,l,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_11-3-面向对象、设计模式与程序语言词汇-★★" tabindex="-1">11.3 面向对象、设计模式与程序语言词汇 ★★ <a class="header-anchor" href="#_11-3-面向对象、设计模式与程序语言词汇-★★" aria-label="Permalink to &quot;11.3 面向对象、设计模式与程序语言词汇 ★★&quot;">​</a></h1><h3 id="_3-1-面向对象" tabindex="-1">3.1 面向对象 <a class="header-anchor" href="#_3-1-面向对象" aria-label="Permalink to &quot;3.1 面向对象&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>关键词</th></tr></thead><tbody><tr><td>class / object / instance</td><td>类 / 对象 / 实例</td><td>blueprint / concrete occurrence</td></tr><tr><td>encapsulation</td><td>封装</td><td>hide internal details</td></tr><tr><td>inheritance</td><td>继承</td><td>derive from a base class</td></tr><tr><td>polymorphism</td><td>多态</td><td>same interface, different behavior</td></tr><tr><td>abstraction</td><td>抽象</td><td>focus on essential features</td></tr><tr><td>interface</td><td>接口</td><td>contract of operations</td></tr><tr><td>override</td><td>重写</td><td>subclass replaces inherited behavior</td></tr><tr><td>overload</td><td>重载</td><td>same name, different parameter lists</td></tr></tbody></table><p><code>object</code> 和 <code>instance</code> 在许多上下文中都可表示“对象/实例”，但 <code>class</code> 是蓝图，instance 是按蓝图创建的具体对象。</p><h3 id="_3-2-高频设计模式英文" tabindex="-1">3.2 高频设计模式英文 <a class="header-anchor" href="#_3-2-高频设计模式英文" aria-label="Permalink to &quot;3.2 高频设计模式英文&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pattern</th><th>一句话英文识别</th><th>中文意图</th></tr></thead><tbody><tr><td>Singleton</td><td>ensures a class has only one instance</td><td>保证单实例</td></tr><tr><td>Factory Method</td><td>lets subclasses decide which class to instantiate</td><td>由子类决定实例化谁</td></tr><tr><td>Observer</td><td>one-to-many dependency; observers are notified</td><td>状态变化时通知观察者</td></tr><tr><td>Strategy</td><td>encapsulates interchangeable algorithms</td><td>封装可替换算法</td></tr><tr><td>Adapter</td><td>converts one interface into another expected by clients</td><td>转换接口</td></tr><tr><td>Decorator</td><td>adds responsibilities to an object dynamically</td><td>动态增加职责</td></tr><tr><td>Proxy</td><td>controls access to another object</td><td>控制对象访问</td></tr><tr><td>Facade</td><td>provides a unified interface to a subsystem</td><td>为子系统提供统一入口</td></tr></tbody></table><h3 id="_3-3-编译与算法" tabindex="-1">3.3 编译与算法 <a class="header-anchor" href="#_3-3-编译与算法" aria-label="Permalink to &quot;3.3 编译与算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th></tr></thead><tbody><tr><td>lexical analysis</td><td>词法分析，把字符流变成 token</td></tr><tr><td>syntax analysis / parsing</td><td>语法分析，检查结构</td></tr><tr><td>semantic analysis</td><td>语义分析，检查类型和含义</td></tr><tr><td>intermediate code</td><td>中间代码</td></tr><tr><td>optimization</td><td>优化</td></tr><tr><td>executable</td><td>可执行文件；也可作形容词“可执行的”</td></tr><tr><td>recursion</td><td>递归</td></tr><tr><td>iteration</td><td>迭代</td></tr><tr><td>greedy algorithm</td><td>贪心算法</td></tr><tr><td>dynamic programming</td><td>动态规划</td></tr><tr><td>divide and conquer</td><td>分治</td></tr><tr><td>time/space complexity</td><td>时间/空间复杂度</td></tr></tbody></table><p><strong>应试动作</strong>：模式名不只背中文。看到 <code>notified automatically</code> 想 Observer；<code>interchangeable algorithms</code> 想 Strategy；<code>convert an interface</code> 想 Adapter；<code>only one instance</code> 想 Singleton。</p><hr>',10)])])}const m=d(o,[["render",n]]);export{_ as __pageData,m as default};
